declare module "bun" {
  interface SyncSubprocess {
    exitCode: number;
    success: boolean;
    stdout: Uint8Array;
    stderr: Uint8Array;
    signalCode: string | null;
  }
  function spawnSync(
    argv: string[],
    options?: {
      stdin?: "ignore" | "inherit";
      stdout?: "ignore" | "inherit" | "pipe";
      stderr?: "ignore" | "inherit" | "pipe";
    },
  ): SyncSubprocess;
}
